-- Tenant rows are hidden unless a transaction explicitly sets app.tenant_id.
-- The runtime role MUST NOT be superuser or BYPASSRLS. Do not run production with the migration role.
-- Null tenantId is an unassigned legacy record; it is never visible through these policies.
ALTER TABLE "zoho_mail_tokens" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "zoho_mail_tokens" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "zoho_mail_tokens" USING ("tenantId" = NULLIF(current_setting('app.tenant_id', true), '')) WITH CHECK ("tenantId" = NULLIF(current_setting('app.tenant_id', true), ''));
