-- Same-tenant foreign keys supplement legacy single-column relations.
ALTER TABLE "whatsapp_messages" ADD CONSTRAINT "whatsapp_messages_conversationId_tenant_fk" FOREIGN KEY ("conversationId", "tenantId") REFERENCES "whatsapp_conversations" ("id", "tenantId");
ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_cartId_tenant_fk" FOREIGN KEY ("cartId", "tenantId") REFERENCES "carts" ("id", "tenantId");
ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_equipmentId_tenant_fk" FOREIGN KEY ("equipmentId", "tenantId") REFERENCES "equipments" ("id", "tenantId");
ALTER TABLE "equipments" ADD CONSTRAINT "equipments_categoryId_tenant_fk" FOREIGN KEY ("categoryId", "tenantId") REFERENCES "categories" ("id", "tenantId");
ALTER TABLE "equipment_units" ADD CONSTRAINT "equipment_units_equipmentId_tenant_fk" FOREIGN KEY ("equipmentId", "tenantId") REFERENCES "equipments" ("id", "tenantId");
ALTER TABLE "quote_items" ADD CONSTRAINT "quote_items_equipmentId_tenant_fk" FOREIGN KEY ("equipmentId", "tenantId") REFERENCES "equipments" ("id", "tenantId");
ALTER TABLE "quote_items" ADD CONSTRAINT "quote_items_quoteId_tenant_fk" FOREIGN KEY ("quoteId", "tenantId") REFERENCES "quotes" ("id", "tenantId");
ALTER TABLE "rental_items" ADD CONSTRAINT "rental_items_equipmentid_tenant_fk" FOREIGN KEY ("equipmentid", "tenantId") REFERENCES "equipments" ("id", "tenantId");
ALTER TABLE "rental_items" ADD CONSTRAINT "rental_items_rentalid_tenant_fk" FOREIGN KEY ("rentalid", "tenantId") REFERENCES "rentals" ("id", "tenantId");
ALTER TABLE "rentals" ADD CONSTRAINT "rentals_quoteId_tenant_fk" FOREIGN KEY ("quoteId", "tenantId") REFERENCES "quotes" ("id", "tenantId");
ALTER TABLE "maintenances" ADD CONSTRAINT "maintenances_equipmentId_tenant_fk" FOREIGN KEY ("equipmentId", "tenantId") REFERENCES "equipments" ("id", "tenantId");
ALTER TABLE "payments" ADD CONSTRAINT "payments_quoteId_tenant_fk" FOREIGN KEY ("quoteId", "tenantId") REFERENCES "quotes" ("id", "tenantId");
ALTER TABLE "payments" ADD CONSTRAINT "payments_rentalId_tenant_fk" FOREIGN KEY ("rentalId", "tenantId") REFERENCES "rentals" ("id", "tenantId");
ALTER TABLE "quote_adjustments" ADD CONSTRAINT "quote_adjustments_quoteId_tenant_fk" FOREIGN KEY ("quoteId", "tenantId") REFERENCES "quotes" ("id", "tenantId");
ALTER TABLE "client_documents" ADD CONSTRAINT "client_documents_rentalId_tenant_fk" FOREIGN KEY ("rentalId", "tenantId") REFERENCES "rentals" ("id", "tenantId");
ALTER TABLE "deliveries" ADD CONSTRAINT "deliveries_rentalId_tenant_fk" FOREIGN KEY ("rentalId", "tenantId") REFERENCES "rentals" ("id", "tenantId");
ALTER TABLE "contracts" ADD CONSTRAINT "contracts_rentalId_tenant_fk" FOREIGN KEY ("rentalId", "tenantId") REFERENCES "rentals" ("id", "tenantId");
ALTER TABLE "payment_attempts" ADD CONSTRAINT "payment_attempts_paymentId_tenant_fk" FOREIGN KEY ("paymentId", "tenantId") REFERENCES "payments" ("id", "tenantId");
CREATE UNIQUE INDEX rentals_tenant_quote_unique ON rentals ("tenantId", "quoteId") WHERE "tenantId" IS NOT NULL AND "quoteId" IS NOT NULL;
